CREATE OR REPLACE FUNCTION public.sgp_aplicar_export_diario(p_token text, p_linea text, p_nombre_archivo text, p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE item jsonb; expected_year integer; expected_week integer; key text;
 seen text[]:=ARRAY[]::text[]; existing public.sgp_producciones%rowtype; response jsonb;
BEGIN
 IF jsonb_typeof(p_datos) IS DISTINCT FROM 'array' OR jsonb_array_length(p_datos)=0
 THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_DATA_INVALID'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_datos) LOOP
  key:=nullif(btrim(item->>'key_produccion'),'');
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR key IS NULL
   OR coalesce(item->>'anio','') !~ '^[0-9]{4}$'
   OR coalesce(item->>'semana_actual','') !~ '^[0-9]{1,2}$'
   OR nullif(btrim(item->>'id_linea'),'') IS DISTINCT FROM p_linea
  THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_EXPLICIT_PERIOD_REQUIRED'; END IF;
  expected_year:=(item->>'anio')::integer;expected_week:=(item->>'semana_actual')::integer;
  IF expected_year NOT BETWEEN 2020 AND 2100 OR expected_week NOT BETWEEN 1 AND 53
   OR key=ANY(seen) THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_PERIOD_AMBIGUOUS'; END IF;
  seen:=array_append(seen,key);
  -- Lock the existing production before delegating. This prevents a concurrent
  -- reprogramming from changing the year between validation and Export writes.
  SELECT * INTO existing FROM public.sgp_producciones WHERE key_produccion=key FOR UPDATE;
  IF FOUND AND (existing.id_linea IS DISTINCT FROM p_linea
    OR existing.anio IS DISTINCT FROM expected_year) THEN
   RAISE EXCEPTION 'PDT_EXPORT_YEAR_IMMUTABLE: %',key;
  END IF;
 END LOOP;
 -- Preserve installed Export authorization, reconciliation, history and response.
 response:=sgp_pdt_manual.original_aplicar_export_diario(p_token,p_linea,p_nombre_archivo,p_datos);
 -- The certified writer returns ok=true only after all writes complete. Fail closed
 -- on any future JSON rejection and roll back the delegated transaction as well.
 IF response->>'ok' IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION 'PDT_EXPORT_YEAR_DELEGATED_NOT_OK';
 END IF;
 -- Verify the original writer applied the week without changing the year.
 -- Missing rows remain the original writer's responsibility (e.g. FUERA_BASE).
 FOR item IN SELECT value FROM jsonb_array_elements(p_datos) LOOP
  key:=btrim(item->>'key_produccion');expected_year:=(item->>'anio')::integer;
  expected_week:=(item->>'semana_actual')::integer;
  SELECT * INTO existing FROM public.sgp_producciones WHERE key_produccion=key FOR UPDATE;
  IF FOUND THEN
   IF existing.id_linea IS DISTINCT FROM p_linea OR existing.anio IS DISTINCT FROM expected_year
    OR coalesce(existing.semana_actual,existing.semana_base) IS DISTINCT FROM expected_week
   THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_RESULT_MISMATCH: %',key; END IF;
  END IF;
 END LOOP;
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.original_aplicar_export_diario(p_token text, p_linea text, p_nombre_archivo text, p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_usuario text;v_preview jsonb;v_carga uuid;v_actualizados int:=0;v_nuevos int:=0;v_ausentes int:=0;r record;oldrow sgp_producciones%rowtype;newrow jsonb;newens numeric;newemp numeric;newensamblado numeric;
begin v_usuario:=sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR']);v_preview:=sgp_previsualizar_export_diario(p_token,p_linea,p_datos);
insert into sgp_cargas_diarias(tipo_fuente,id_linea,usuario,nombre_archivo,registros_recibidos)values('EXPORT',p_linea,v_usuario,p_nombre_archivo,(v_preview->>'recibidos')::int)returning id_carga_diaria into v_carga;
update sgp_producciones p set presente_ultimo_export=false,ultima_carga_diaria=v_carga where p.id_linea=p_linea and coalesce(p.activa,'SI')='SI' and p.semana_base in(select distinct(x->>'semana_actual')::int from jsonb_array_elements(p_datos)x where nullif(x->>'semana_actual','')is not null)and not exists(select 1 from jsonb_array_elements(p_datos)x where x->>'key_produccion'=p.key_produccion);get diagnostics v_ausentes=row_count;
for r in select x from jsonb_array_elements(p_datos)x loop
 select * into oldrow from sgp_producciones p where p.key_produccion=r.x->>'key_produccion';
 if found then
  newens:=nullif(r.x->>'saldo_ensamble','')::numeric;newemp:=nullif(r.x->>'saldo_empaque','')::numeric;newensamblado:=nullif(r.x->>'ensamblado','')::numeric;
  update sgp_producciones p set semana_actual=nullif(r.x->>'semana_actual','')::int,saldo_ensamble=newens,saldo_empaque=newemp,estado_reserva_al=r.x->>'estado_reserva_al',porc_vidrio=nullif(r.x->>'porc_vidrio','')::numeric,estado_produccion=r.x->>'estado_produccion',ensamblado=newensamblado,empacado=nullif(r.x->>'empacado','')::numeric,reserva_al=coalesce(r.x->>'reserva_al',p.reserva_al),presente_ultimo_export=true,ultima_vez_export=now(),ultima_carga_diaria=v_carga,saldos_inicializados=true,fecha_inicializacion_saldos=coalesce(p.fecha_inicializacion_saldos,now()),fecha_actualizacion=now() where p.key_produccion=r.x->>'key_produccion';
  select to_jsonb(p) into newrow from sgp_producciones p where p.key_produccion=r.x->>'key_produccion';
  if oldrow.saldos_inicializados and coalesce(oldrow.ensamblado,0)=0 and coalesce(newensamblado,0)>0 and coalesce(newens,0)>0 then insert into sgp_eventos_actualizacion(id_lote,fuente,tipo_evento,clave,datos)values(v_carga,'EXPORT','ABIERTA_ENSAMBLE',oldrow.key_produccion,newrow);end if;
  if oldrow.saldos_inicializados and coalesce(oldrow.saldo_ensamble,0)>0 and coalesce(newens,0)=0 then insert into sgp_eventos_actualizacion(id_lote,fuente,tipo_evento,clave,datos)values(v_carga,'EXPORT','ENSAMBLADA_COMPLETA',oldrow.key_produccion,newrow);end if;
  if oldrow.saldos_inicializados and (coalesce(oldrow.saldo_ensamble,0)>0 or coalesce(oldrow.saldo_empaque,0)>0) and coalesce(newens,0)=0 and coalesce(newemp,0)=0 then insert into sgp_eventos_actualizacion(id_lote,fuente,tipo_evento,clave,datos)values(v_carga,'EXPORT','ORDEN_COMPLETADA',oldrow.key_produccion,newrow);end if;
  v_actualizados:=v_actualizados+1;
  insert into sgp_export_diario_historial(id_carga_diaria,key_produccion,id_linea,produccion_id,produccion,sistema,semana_actual,saldo_ensamble,saldo_empaque,estado_reserva_al,porc_vidrio,presente,datos)values(v_carga,r.x->>'key_produccion',p_linea,r.x->>'id',r.x->>'produccion',r.x->>'sistema',nullif(r.x->>'semana_actual','')::int,newens,newemp,r.x->>'estado_reserva_al',nullif(r.x->>'porc_vidrio','')::numeric,true,r.x);
 else v_nuevos:=v_nuevos+1;end if;
end loop;
insert into sgp_export_diario_historial(id_carga_diaria,key_produccion,id_linea,produccion_id,produccion,sistema,semana_actual,saldo_ensamble,saldo_empaque,estado_reserva_al,porc_vidrio,presente,datos)select v_carga,p.key_produccion,p.id_linea,p.id,p.produccion,p.sistema,p.semana_actual,p.saldo_ensamble,p.saldo_empaque,p.estado_reserva_al,p.porc_vidrio,false,'{}'::jsonb from sgp_producciones p where p.id_linea=p_linea and p.ultima_carga_diaria=v_carga and p.presente_ultimo_export=false;
update sgp_cargas_diarias set registros_actualizados=v_actualizados,registros_nuevos=v_nuevos,registros_ausentes=v_ausentes,detalle=jsonb_build_object('linea',p_linea,'semanas',v_preview->'semanas','saldos_inicializados',true)where id_carga_diaria=v_carga;
return jsonb_build_object('ok',true,'id_carga_diaria',v_carga,'linea',p_linea,'actualizados',v_actualizados,'fuera_base',v_nuevos,'ausentes',v_ausentes,'saldos_inicializados',true,'semanas',v_preview->'semanas');end$function$
